'use strict';

// Presentation for the fictional conversation profile. No provider calls.
function releaseDetail(component) {
  const method = component === 'method';
  const entries = method ? activeProfile.changes : prototypeRelease.changes;
  return `<h2 id="detail-title">${method?'Методика: '+esc(activeProfile.method):'Что нового в интерфейсе'}</h2>
    <div class="arrow-flow">${badge(method?activeProfile.methodVersion:prototypeRelease.version,'green')}${badge('Демо · 9 октября 2026','orange')}</div>
    <p>${method?'Применима к профилю '+esc(activeProfile.name)+'.':'Общие изменения кабинета для всех профилей.'} Это описание прототипа, не журнал выпущенного backend.</p>
    <ul class="detail-list">${entries.map(([label,value])=>`<li><strong>${esc(label)}</strong>${esc(value)}</li>`).join('')}</ul>
    <h3>Ранее в прототипе</h3><p>${method?(isConversation()?'Это первый демонстрационный выпуск отдельной разговорной политики.':'Базовые задания и простая лексика одного профиля.'):'0.1.0-demo: восемь разделов, карточки оснований, поиск и вымышленные учебные данные.'}</p>
    <div class="notice info section-space">${icon('info')}<div>Версия UI, версия методики и версия документа плана — разные вещи. Старый урок показывает свою методику, а не текущую.</div></div>`;
}
function familyDetail() {
  return `<h2 id="detail-title">Семейные профили</h2>${badge('Запланировано · backend не подключён','orange')}
    <p class="section-space">Можно будет добавлять других членов семьи. У каждого — собственная цель, план, методика, словарь и история.</p>
    <ul class="detail-list"><li><strong>1. Создать учебный профиль</strong>Имя и цель. Начальный уровень — предварительная информация, пока не проверен.</li><li><strong>2. Выбрать методику</strong>Основа английского или разговорная практика; другие методики можно добавить отдельно.</li><li><strong>3. Настроить личный доступ</strong>Ученик видит свои данные; администратор — явно разрешённые профили.</li><li><strong>4. Согласовать первый план</strong>Темы, нагрузка и предпочтения по исправлениям.</li></ul>
    <p class="rule-note">Переключатель этого прототипа показывает два вымышленных профиля. Он не создаёт аккаунты и не подтверждает серверную изоляцию. Для детей методика прорабатывается с учётом возраста.</p>`;
}
function familyManagementCard() {
  return `<section class="card section-space"><div class="card-head"><h2>Семейные профили</h2>${badge('2 демопрофиля','')}</div><p class="chart-note">Для каждого — своя цель, методика и история. Добавление следующих членов семьи предусмотрено в реальной админке.</p>${detailButton('Как добавить члена семьи','family','all','soft')}</section>`;
}
function correctionPreview() {
  const a = observations.find(a=>a.outcome==='incorrect');
  return `<div class="dialogue-preview"><span class="speaker">Катя · вымышленная реплика</span><p>${esc(a.text)}</p><span class="speaker teacher">Преподаватель · исправление и продолжение</span><p>${esc(a.correction)} <span>${esc(a.followup)}</span></p></div><p class="rule-note">Одна важная правка после законченной мысли. Речь преподавателя не считается ответом ученицы.</p>${detailButton('Посмотреть основание','evidence',a.id,'ghost')}`;
}
function conversationOverview() {
  return `${statusNotice()}<div class="grid grid-2"><section class="hero conversation-hero"><div><div class="eyebrow">Разговорная цель · Катя</div><h2>Говорить свободнее.<br>Выражать мысль точнее.</h2><p>Разговор на интересную тему, короткие исправления главного и продолжение беседы. Предполагаемый уровень B2 — ещё без диагностики.</p><div class="hero-meta">${navigateButton('Темы и мой план','program','primary')}${badge(demoPreferences.katya.grammar?'Практика по согласию':'Без грамматических заданий','dark')}</div></div><div class="hero-visual"><div class="stage-circle"><strong>C1</strong></div><small>уровень речи агента</small></div></section><section class="card today"><div class="card-head"><span class="eyebrow">Следующий разговор · demo</span>${icon('arrow')}</div><div class="next-title">Что делает поездку<br>запоминающейся?</div><p class="next-description">Расскажи о неожиданном впечатлении. Преподаватель поддержит тему и задаст уточнение.</p><div class="tiny-meta"><span>${icon('help')}Свободная тема тоже доступна</span></div>${detailButton('Выбрать тему','topics','all','soft')}</section></div>
    ${statCards()}<div class="grid grid-2 section-space"><section class="card"><div class="card-head"><h2>Как выглядят исправления</h2>${badge('В ходе беседы','purple')}</div>${correctionPreview()}</section><section class="card"><div class="card-head"><h2>Мой разговорный маршрут</h2>${navigateButton('Весь план','program','ghost')}</div>${routePreview()}<p class="rule-note">Тема — повод говорить. Свободную тему можно выбрать на любом этапе.</p><div class="health-pair"><span>${icon('check')}${demoPreferences.katya.grammar?'Практика разрешена в демо':'Грамматические задания выключены'}</span></div></section></div>
    <div class="grid grid-2 section-space"><section class="card"><div class="card-head"><h2>Последний разбор</h2>${badge(ui.scenario==='failure'?'Не применён':'Применён',ui.scenario==='failure'?'orange':'green')}</div><p class="chart-note">${ui.scenario==='failure'?'Ответы сохранены; план бесед не менялся.':'В следующем разговоре вернуться к конкретному событию и дать возможность употребить исправленную форму самостоятельно.'}</p>${detailButton('Решение и исходные реплики','job',jobs[0].id,'soft')}</section><section class="card"><h2>Перед следующим разговором</h2><p class="chart-note">Можно подумать о поездке или впечатлении, которое хочется обсудить. Это необязательная подготовка, без worksheet.</p>${detailButton('Посмотреть вариант','conversation-prep','all','ghost')}<p class="rule-note">Нагрузка и необходимость закрепления ещё не согласованы с Катей.</p></section></div><p class="live-date">Вымышленный текстовый сценарий · не оценка произношения, скорости речи или уровня Кати.</p>`;
}
function conversationProgram() {
  const plans = {current:['Рассказать о неожиданном впечатлении','Ответить на уточнение и задать встречный вопрос','Выбрать свободную тему'],future:['Обсудить фильм и объяснить свою позицию','Вернуться к исправлению в новой беседе','Свободная тема по желанию'],carry:['Продолжить мысль о поездке без спешки']};
  return `<div class="notice info">${icon('info')}<div><strong>Моя цель: свободно и корректно общаться</strong><br>Начальный маршрут — демонстрация. Реальный план сформируется после знакомства и разговора на комфортные темы.</div></div><div class="grid grid-2"><section><div class="card-head"><h2>Пять разговорных направлений</h2>${badge('Гибкий маршрут','purple')}</div><div class="program-list">${stages.map((s,i)=>`<button class="stage-card ${i===0?'current':''}" data-action="detail" data-type="stage" data-id="${s.id}"><span class="step-number">${i+1}</span><span class="stage-content"><h3>${s.title}</h3><p>${s.forms}</p></span>${icon('chevron')}</button>`).join('')}</div></section><section><div class="card"><h2>План беседы</h2><div class="tabs" role="group" aria-label="Выбор плана">${[['current','Текущий'],['future','Будущий'],['carry','Переносы']].map(([v,t])=>`<button class="tab ${planTab===v?'active':''}" data-action="plan-tab" data-value="${v}" aria-pressed="${planTab===v}">${t}</button>`).join('')}</div>${plans[planTab].map((t,i)=>`<div class="list-row"><span class="row-icon">${i+1}</span><div class="row-copy"><h3>${t}</h3><p>${planTab==='carry'?'Не потерять мысль':'Диалог, без задания на грамматическую форму'}</p></div></div>`).join('')}<p class="rule-note">Согласованная длительность пока не задана. План не завершает беседу автоматически.</p></div><div class="card section-space"><h2>Тема по настроению</h2><p class="chart-note">Путешествия, фильмы, повседневные решения или твоя тема. Любую можно пропустить.</p>${detailButton('Посмотреть темы','topics','all','soft')}</div><div class="card section-space"><h2>Ближайший фокус корректности</h2><p class="chart-note">Рассказ о конкретном событии — через смысл беседы, без упражнений на времена.</p>${detailButton('Откуда появился фокус','job',jobs[0].id,'ghost')}</div></section></div>`;
}
function conversationProgress() {
  const s=stats();
  return `<div class="notice info">${icon('info')}<div>Оценены отдельные коммуникативные цели и выбранные формы. Эти наблюдения не оценивают весь разговор и не устанавливают уровень CEFR.</div></div><div class="grid grid-3"><div class="card stat"><div class="stat-label">Удалось без подсказки</div><div class="stat-number">${fraction(s)}</div><div class="stat-foot">По выбранным фокусам разговора</div></div><div class="card stat"><div class="stat-label">Получилось с помощью</div><div class="stat-number">${s.assisted}</div><div class="stat-foot">Учитывается отдельно</div></div><div class="card stat"><div class="stat-label">Проверка в другой беседе</div><div class="stat-number">${s.later}</div><div class="stat-foot">Самостоятельная проверка позднее</div></div></div>
    <section class="card section-space"><div class="card-head"><h2>Что помогает свободно общаться</h2>${detailButton('Как считаем','metrics','all','ghost')}</div>${skills.map(skill=>`<button class="link-row" data-action="detail" data-type="skill" data-id="${skill.id}"><div class="list-row"><span class="row-icon ${skill.color}">${icon('progress')}</span><div class="row-copy"><h3>${skill.title}</h3><p>${skill.subtitle}</p></div><span class="fraction">${fraction(stats(skill.id))}</span>${icon('chevron')}</div></button>`).join('')}<p class="rule-note">Каждая дробь раскрывает исходные реплики и помощь. Один ответ не означает устойчивого освоения.</p></section><div class="grid grid-2 section-space"><section class="card"><h2>Наблюдения по беседам</h2>${chart()}</section><section class="card"><h2>Журнал исправлений</h2>${correctionPreview()}<p class="rule-note">Произношение и паузы в этой текстовой демонстрации не измеряются.</p></section></div>`;
}
function conversationLessons() {
  return `<div class="tabs" role="group" aria-label="Беседы или закрепление">${[['lessons','История бесед'],['homework','Разговорное закрепление']].map(([v,t])=>`<button class="tab ${lessonTab===v?'active':''}" data-action="lesson-tab" data-value="${v}" aria-pressed="${lessonTab===v}">${t}</button>`).join('')}</div>${lessonTab==='homework'?`<div class="notice info">${icon('info')}<div>Обязательные домашние задания не назначены. Разговорное закрепление и нагрузку нужно согласовать с Катей.</div></div><section class="card"><h2>Подготовить мысль, а не упражнение</h2><p class="chart-note">Если хочется, вспомни одно впечатление и почему оно запомнилось. На следующей беседе обсудим его своими словами.</p>${detailButton('Открыть демочерновик','conversation-prep','all','soft')}</section>`:`<section class="card"><h2>Сохранённые беседы · demo</h2>${lessons.filter(inPeriod).map(l=>`<button class="link-row" data-action="detail" data-type="lesson" data-id="${l.id}"><div class="list-row"><span class="row-icon">${icon('lessons')}</span><div class="row-copy"><h3>${l.title}</h3><p>${dateLabel(l.date,true)} · ${observations.filter(a=>a.lesson===l.id).length} сохранённых наблюдения · вымышленные данные</p></div>${icon('chevron')}</div></button>`).join('')}</section>`}`;
}
function conversationMethodologist() {
  const visible=jobs.filter(inPeriod).map(j=>j.id===jobs[0].id&&ui.scenario==='failure'?{...j,status:'failed'}:j).filter(j=>jobState==='all'||j.status===jobState);
  return `${statusNotice()}<div class="grid grid-3"><section class="card"><h2>От реплики к плану</h2><p class="chart-note">Найти важный фокус и проверить его в следующей беседе. Грамматический блок не добавлять.</p></section><section class="card"><h2>Две роли</h2><p class="chart-note">Преподаватель исправляет во время диалога. Методолог разбирает сохранённые наблюдения и планирует следующую тему.</p></section><section class="card"><h2>Что уже сохранено</h2><p class="chart-note">${observations.length} вымышленных наблюдений. Сбой разбора не удаляет исходные ответы.</p></section></div><section class="card section-space"><div class="card-head"><h2>Журнал разговорной методики</h2><select class="select" id="job-state" aria-label="Статус разбора"><option value="all">Все статусы</option>${Object.entries(jobLabels).map(([v,[t]])=>`<option value="${v}" ${v===jobState?'selected':''}>${t}</option>`).join('')}</select></div>${visible.length?visible.map(j=>`<article class="job-card"><div class="job-time"><strong>${dateLabel(j.date)}</strong>${j.time}</div><div class="job-copy">${badge(...jobLabels[j.status])}<h3 class="section-space">${j.status==='failed'?'Разбор не завершён':j.title}</h3><p>${j.status==='failed'?'Ответы сохранены; изменения плана не применены.':j.why}</p><div class="job-meta">${j.evidence.length} наблюдения · ${activeProfile.methodVersion}</div></div>${detailButton('Разбор','job',j.id,'small')}</article>`).join(''):'<div class="empty"><h3>Таких разборов пока нет</h3><p>Выбери другой статус или период.</p></div>'}</section>`;
}
function conversationMaterials() {
  return `${materialsView()}<section class="card section-space"><h2>Как работает разговорная практика</h2><div class="grid grid-3">${[['recast','Исправление в контексте','Дать закончить мысль, коротко исправить главное и продолжить тему.'],['followup','Развитие мысли','Уточнение, встречный вопрос и собственный пример вместо серии упражнений.'],['natural-reuse','Естественное повторное использование','Похожая мысль в следующем разговоре, без обязательного повторения за агентом.']].map(([id,title,body])=>`<div class="method-card"><h3>${title}</h3><p>${body}</p>${detailButton('Как применяется','method',id,'ghost')}</div>`).join('')}</div></section>`;
}
function conversationSettings() {
  const grammar=demoPreferences.katya.grammar;
  return `<div class="notice info">${icon('info')}<div>Учебные настройки — демонстрация. Изменение разрешения грамматики живёт в памяти вкладки. Тема интерфейса сохраняется отдельно.</div></div><div class="grid grid-2"><section class="card"><h2>Цель и разговорный формат</h2>${[['Цель','Свободно и корректно говорить','Развивать мысль, поддерживать диалог и точнее выражаться'],['Уровень ученицы','Примерно B2','Предварительно, со слов пользователя; без диагностики'],['Речь агента','Около C1','Естественная и точная; упрощение по просьбе'],['Исправления','После законченной мысли','Одна важная правка, затем продолжить тему'],['Нагрузка','Не согласована','Уточнить с Катей; не брать настройки Александра'],['Темы','План + свободный выбор','Тему можно добавить, пропустить или заменить']].map(([t,v,d])=>`<div class="settings-row"><div><strong>${t}</strong><p>${d}</p></div><span class="settings-value">${v}</span></div>`).join('')}</section><section><div class="card"><div class="card-head"><h2>Грамматические задания</h2>${badge(grammar?'Разрешены в демо':'Выключены',grammar?'orange':'green')}</div><p class="chart-note">Исправления в разговоре доступны всегда. Пропуски, таблицы времён и серии повторов по умолчанию не предлагаются.</p>${grammar?button('Выключить в демопрофиле','disable-grammar','','soft',''):detailButton('Посмотреть возможность включения','grammar','all','soft')}<p class="rule-note">Включение требует отдельного согласия Кати. История и методика Александра не меняются. Реальные задания здесь не генерируются.</p></div><div class="card section-space"><h2>Технические сведения</h2><p class="chart-note">Демо · API и личный вход не подключены · модельных вызовов нет · learner_id: katya.</p>${detailButton('Версия разговорной методики','release','method','ghost')}</div><div class="card section-space"><h2>Экспорт демообзора</h2><p class="chart-note">Только выбранный профиль, период и правила показателей.</p>${button('Скачать JSON','export','','soft','download')}</div>${familyManagementCard()}</section></div>`;
}
function conversationDetail(type,id) {
  const title=t=>`<h2 id="detail-title">${esc(t)}</h2>`;
  const absent=()=>title('Запись не найдена')+'<p>В этом demo-профиле нет такой записи.</p>';
  if(type==='topics')return `${title('Выбери тему разговора')}<p>Демонстрационные варианты. Реальные интересы и план согласуются с Катей.</p>${materials.map(m=>`<button class="link-row" data-action="detail" data-type="material" data-id="${m.id}"><div class="list-row"><span class="row-icon purple">${icon('materials')}</span><div class="row-copy"><h3>${m.title}</h3><p>${m.summary}</p></div>${icon('chevron')}</div></button>`).join('')}`;
  if(type==='stage') {
    const s=stages.find(s=>s.id===id);if(!s)return absent();
    return `${title(s.title)}${badge('Разговорное направление','purple')}<p class="section-space">${s.target}</p><h3>Пример открытого вопроса</h3><div class="answer">${s.prompt}</div><h3>Что будем наблюдать</h3><p>${s.criterion}</p><h3>Почему это полезно</h3><p>${s.reason}</p><p class="rule-note">Это направление можно сочетать со свободной темой. Обязательной грамматической лестницы нет.</p>${detailButton('Выбрать тему','topics','all','soft')}`;
  }
  if(type==='evidence') {
    const a=observations.find(a=>a.id===id);if(!a)return absent();
    return `${title('Реплика Кати · демопример')}<span class="code-id">${a.id}</span><h3>Контекст</h3><p>${a.prompt}</p><div class="answer ${a.outcome==='incorrect'?'wrong':''}">${esc(a.text)}</div><div class="arrow-flow">${badge(outcomeLabel[a.outcome],a.outcome==='incorrect'?'orange':'green')}${badge(assistanceLabel[a.assistance],'')}</div><div class="key-value"><span>Наблюдаемый фокус</span><strong>${a.focus}</strong></div><p class="rule-note">Оценка относится к выбранному фокусу, не ко всей реплике или уровню ученицы.</p>${a.outcome==='incorrect'?`<h3>Исправление преподавателя</h3><div class="answer">${a.correction}</div><h3>Продолжение беседы</h3><p>${a.followup}</p><p class="rule-note">Исправление не становится самостоятельным результатом Кати.</p>`:''}<div class="drawer-actions">${detailButton('Исходная беседа','lesson',a.lesson,'primary')}${detailButton('Разбор','job',lessons.find(l=>l.id===a.lesson).job)}</div>`;
  }
  if(type==='lesson') {
    const l=lessons.find(l=>l.id===id);if(!l)return absent();
    return `${title(l.title)}<span class="code-id">${l.id}</span><div class="key-value"><span>Дата</span><strong>${dateLabel(l.date,true)}</strong></div><div class="key-value"><span>Методика этой беседы</span><strong>Свободный разговор · ${l.id==='katya-lesson-03'?'0.9-demo':'1.0-demo'}</strong></div><p class="rule-note">Текущая версия: ${activeProfile.methodVersion}. Версии бесед — демонстрационные снимки.</p><h3>Сохранённые наблюдения</h3>${evidenceRows(observations.filter(a=>a.lesson===id).map(a=>a.id))}<h3>Следующий разговор</h3><p>Продолжить мысль или выбрать новую тему; проверить полезное исправление в естественном ответе.</p><div class="drawer-actions">${detailButton('Разбор методолога','job',l.job,'primary')}${detailButton('Необязательная подготовка','conversation-prep','all')}</div>`;
  }
  if(type==='job') {
    const j=jobs.find(j=>j.id===id);if(!j)return absent();
    const failed=ui.scenario==='failure'&&j.id===jobs[0].id;
    return `${title('Разбор беседы · Катя')}${badge(...jobLabels[failed?'failed':j.status])}<div class="key-value"><span>job_id</span><strong>${j.id}</strong></div><div class="key-value"><span>Методика на входе</span><strong>${j.lesson==='katya-lesson-03'?'0.9-demo':'1.0-demo'}</strong></div><h3>Исходные реплики</h3>${evidenceRows(j.evidence)}${failed?'<div class="notice section-space">Разбор не завершён. Ответы сохранены; учебные изменения не применены.</div>':`<h3>Вывод и решение</h3><p>${j.why}</p><div class="diff before"><small>Раньше</small>${j.before}</div><div class="diff after"><small>Теперь</small>${j.after}</div><p class="rule-note">Демонстрационная гипотеза. Результат проверяется в следующем самостоятельном ответе.</p>`}<div class="drawer-actions">${detailButton('Беседа','lesson',j.lesson,'soft')}${navigateButton('План разговоров','program')}</div>`;
  }
  if(type==='material') {
    const m=materials.find(m=>m.id===id);if(!m)return absent();
    return `${title(m.title)}${badge(m.origin,'purple')}<p class="section-space">${m.summary}</p><div class="answer">${m.text}</div><p class="muted">${m.meaning}</p><h3>Как продолжить</h3><p>Дать собственный пример, ответить на уточнение или сменить тему по желанию. Без заучивания готового ответа.</p><p class="rule-note">Это повод для беседы, не наблюдение уровня ученицы. Использований в demo: ${m.used}.</p>${m.lesson?detailButton('Связанная беседа','lesson',m.lesson,'soft'):navigateButton('Темы и план','program','soft')}`;
  }
  if(type==='method')return `${title({recast:'Исправление в контексте',followup:'Развитие мысли','natural-reuse':'Естественное повторное использование'}[id]||'Разговорная практика')}<p>Дать закончить мысль, исправить главное коротко и продолжить содержательный разговор.</p><h3>Что считается результатом</h3><p>Самостоятельная реплика в новой беседе. Повтор за образцом и речь агента учитываются отдельно.</p>${detailButton('Пример исправления','evidence','katya-answer-1','soft')}`;
  if(type==='phrase') {
    const p=phrases.find(p=>p.id===id);if(!p)return absent();
    return `${title(p.phrase)}${badge(...lexicalStates[p.state])}<p class="callout-big section-space">${p.meaning}</p><h3>Пример преподавателя</h3><div class="answer">${p.example}</div><p class="rule-note">Этот пример не является ответом Кати.</p><h3>Исходные употребления ученицы</h3>${evidenceRows(p.evidence)}<p class="rule-note">${p.state==='seen'?'Выражение показано; самостоятельного употребления не проверяли.':p.state==='assisted'?'Выражение получилось с подсказкой; это не самостоятельный успех.':'Есть самостоятельное употребление в вымышленной беседе. Нужна последующая проверка в другой ситуации.'}</p><h3>Следующий шаг</h3><p>Естественная возможность выразить похожую мысль в следующем разговоре.</p>`;
  }
  if(type==='conversation-prep')return `${title('Мысли к следующей беседе')}${badge('Необязательно · demo','purple')}<p class="section-space">Вспомни одно впечатление, которое хочется обсудить. Что произошло и почему оно запомнилось? Можно выбрать другую тему.</p><div class="notice info">${icon('info')}<div>Это черновик в памяти вкладки. Не отправляется, не проверяется и очищается после перезагрузки.</div></div><div class="field"><label for="katya-prep">Мысль своими словами, без готового образца</label><textarea id="katya-prep" class="input" data-draft="conversation-prep" placeholder="О чём хочется поговорить…">${esc(draftAnswers['conversation-prep']||'')}</textarea></div><div class="drawer-actions">${button('Оставить демочерновик','save-draft','','primary','check')}</div>`;
  if(type==='grammar')return `${title('Включение грамматической практики')}${badge('Только демопрофиль Кати','orange')}<p class="section-space">По умолчанию задания выключены. Возможность сохраняется на будущее, если Катя сама захочет отдельную практику.</p><label class="consent-box"><input type="checkbox" id="grammar-consent"> В этом демосценарии Катя согласилась включить грамматические задания.</label><button class="btn primary section-space" data-action="enable-grammar" id="enable-grammar" disabled>Разрешить в демопрофиле</button><p class="rule-note">Это проверка интерфейса согласия. Настоящий профиль не изменяется, упражнения не генерируются; разрешение сбросится после reload.</p>`;
  return null;
}
